"""Renders ITERATION63D_REPORT_SR.md from results/iteration63d/analysis.json.gz (DESCRIPTIVE; not confirmatory)."""
import gzip, json, os
HERE = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(os.path.dirname(HERE), "results", "iteration63d")
a = json.load(gzip.open(os.path.join(OUT, "analysis.json.gz"), "rt")); h = a["H63_descriptive"]
L = []; w = L.append
w("# ITERATION63-D: deskriptivna ekstenzija I63 (NEPOTVRDNO) — izveštaj (generisan iz arhive)\n")
w("**Status: DESKRIPTIVNO.** I63 je stao na konačnom STOP-u u fazi snage (zamrznuti kriterijum kalibracije lažne ekvivalencije na granicama ±0,05 nije zadovoljen; zahtev je veoma strog i pri stvarnoj veličini testa 5% prolazi približno 2,1% simulacionih serija; vidi `ITERATION63_REPORT_SR.md`). Ovde je izvršen isti zamrznuti test dizajn (roster, normalizatori, FX-T vektor, n iz I63 skrininga, estimand W/θ₆₃, bootstrap) u novom direktorijumu, bez zaključka o H56a/H63 i bez zamene I63. Izveštava se procena sa intervalima.\n")
w(f"n po ćeliji = {a['n']}. θ₆₃ = {h['estimate']:.4f}; 95% CI [{h['ci95'][0]:.4f}, {h['ci95'][1]:.4f}]; 90% CI [{h['ci90'][0]:.4f}, {h['ci90'][1]:.4f}].\n")
w(f"Deskriptivni dijagnostici zamrznutih pragova, bez inferencijalne odluke: donja 95% granica > 0: {h['positive']}; gornja < 0: {h['negative']}; 90% interval unutar (−0,05; 0,05): {h['equivalent']}. Srednje po mreži: {a['network_means']}; izostavljanje jedne mreže: {a['leave_one_network_out']}.\n")
w("| ćelija | n | srednje d | W(FR) | W(SP) | izv. FR AD-N | izv. FR FX-T | izv. SP AD-N | izv. SP FX-T | med. G FR AD-N | med. G FR FX-T | med. G SP AD-N | med. G SP FX-T |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|")
for k, v in sorted(a["descriptive"].items()):
    w(f"| {k} | {v['n']} | {v['d_mean']:.3f} | {v['W|FR']:.3f} | {v['W|SP']:.3f} | {v['FR|AD-N']['feasible']:.2f} | {v['FR|FX-T']['feasible']:.2f} | {v['SP|AD-N']['feasible']:.2f} | {v['SP|FX-T']['feasible']:.2f} | " + " | ".join("—" if v[k]['median_gap'] is None else f"{v[k]['median_gap']:.4f}" for k in ('FR|AD-N','FR|FX-T','SP|AD-N','SP|FX-T')) + " |")
w("\nMedijana jaza (tabela iznad) je uslovna na izvodljivost; jaz je normalizovan kontinualnim OPF normalizatorom r, koji nije sertifikovani optimum (negativni jazovi su dozvoljeni). θ = 0,05 znači pet procentnih poena razlike očekivanog skora pobede, ne 5% ubrzanja. Bootstrap: 20.000 ponavljanja, nezavisno uzorkovanje semena unutar ćelije, jednake težine ćelija unutar mreže i mreža, `default_rng(63)`, percentili 2,5/97,5 i 5/95. case30/j4 izuzet unapred (eksplicitan OPF neuspeh); case30/j3 je neizvodljiv u svim granama, a case39/j4 gotovo; te veze ostaju u estimandu.")
w("\n## Tumačenje (deskriptivno)\nProcena je mala i neprecizna: interval uključuje nulu, a 90% interval leži unutar (−0,05; 0,05) samo kao informativni dijagnostik, ne kao ekvivalencija. Znak je isti kao u I56 (θ = +0,0205), ali je veličina manja i estimand se razlikuje. Većina doprinosa dolazi iz dve ćelije (case39|3: d = 0,116; case24_ieee_rts|3: d = 0,069); dve ćelije (case30|3, case39|4) su gotovo potpuno neizvodljive pa daju vezu. Po mrežama: case30 negativno, case39 i case24_ieee_rts pozitivno. Nezavisna reprodukcija (Codex 096, `reproduce_i63d.py`) daje identične ćelijske i globalne procene.")
w("\n## Poreklo podataka (odstupanje)\nStablo `gadapt/` promenilo se tokom izvršavanja (opt-in kompenzaciona mutacija); prva provera je ispravno stala. Jednakost rezultata pokazana je ponavljanjem uzorka od 128 zadataka (2,5%) na zamrznutom stablu (128/128 identičnih heševa niza poziva i rezultata); `check` i `analyse` izvršeni su uz privremeno vraćeno zamrznuto stablo. Detalji: `research/results/iteration63d/provenance_addendum.txt`. Jednakost nije pokazana za svaki zadatak.")
w("\n## Ograničenja\nNepotvrdno (I63 STOP); topologije ponovo korišćene; B izabran posle uvida u I61 pilot; kontrast uključuje zasebno podešavanje FX-T po CHT-u; ne identifikuje numerički mehanizam adaptacije.")
open(os.path.join(os.path.dirname(os.path.dirname(HERE)), "research", "ITERATION63D_REPORT_SR.md"), "w").write("\n".join(L) + "\n"); print("written")
